<?php declare(strict_types=1);namespace StudPulse\Bars;use StudPulse\Config;use StudPulse\Database\DB;use StudPulse\Http\{ApiError,Request};use StudPulse\Security\Auth;final class AcademicWatch{private const TASK_SECONDS=8;public function poll():array{$report=['checked'=>0,'attempted'=>0,'remaining'=>0,'oldestMinutes'=>0];if(Config::get('BARS_PROVIDER_MODE')!=='official'){return$report;}$deadline=microtime(true)+25;$due="FROM users u
            LEFT JOIN user_preferences p ON p.user_id=u.id
            JOIN provider_connections c ON c.user_id=u.id AND c.provider='bars' AND c.connection_status='connected'
            JOIN provider_credentials s ON s.connection_id=c.id AND s.expires_at>UTC_TIMESTAMP(6)
            CROSS JOIN (SELECT 'grades' AS resource UNION ALL SELECT 'attendance') resources
            LEFT JOIN bars_academic_watch w ON w.user_id=u.id AND w.resource=resources.resource
            WHERE u.status='active' AND COALESCE(p.preferences->>'$.notifications.academicUpdates','true')='true'
            AND (w.next_check_at IS NULL OR w.next_check_at<=UTC_TIMESTAMP(6))";$dueSince='COALESCE(w.next_check_at,c.last_verified_at,u.created_at)';$candidates=DB::all("SELECT u.id,resources.resource $due
            ORDER BY $dueSince,u.id,resources.resource LIMIT 5");foreach($candidates as$candidate){if($deadline-microtime(true)<self::TASK_SECONDS){break;}$actor=new Auth(new Request(),false);$actor->user=DB::one("SELECT * FROM users WHERE id=? AND status='active'",[$candidate['id']]);if($deadline-microtime(true)<self::TASK_SECONDS){break;}if(!$actor->user){continue;}++$report['attempted'];if($this->checkResource($actor,$candidate['resource'],$deadline)){++$report['checked'];}}$queue=DB::one("SELECT COUNT(*) AS remaining,
            TIMESTAMPDIFF(MINUTE,MIN($dueSince),UTC_TIMESTAMP(6)) AS oldestMinutes $due");$report['remaining']=(int)$queue['remaining'];$report['oldestMinutes']=max(0,(int)$queue['oldestMinutes']);return$report;}public function check(Auth$actor):array{$user=$actor->user['id'];if(Config::get('BARS_PROVIDER_MODE')!=='official'||!$this->enabled($user)){return['checked'=>0,'unavailable'=>0];}$checked=0;foreach(['grades','attendance']as$resource){if($this->checkResource($actor,$resource))$checked++;}return['checked'=>$checked,'unavailable'=>2-$checked];}private function scheduleNext(string$user,string$resource,int$minutes):void{DB::run("INSERT INTO bars_academic_watch(user_id,resource,next_check_at)
            VALUES(?,?,TIMESTAMPADD(MINUTE,?,UTC_TIMESTAMP(6))) AS incoming
            ON DUPLICATE KEY UPDATE next_check_at=incoming.next_check_at",[$user,$resource,$minutes]);}private function checkResource(Auth$actor,string$resource,?float$deadline=null):bool{$user=$actor->user['id'];$this->scheduleNext($user,$resource,15);$bars=new BarsOfficialAdapter($actor,min(microtime(true)+self::TASK_SECONDS,$deadline??INF));try{$result=$resource==='grades'?$bars->getGradesAndAssessments(''):$bars->getAttendance('');}catch(ApiError$error){if($deadline!==null&&($error->status===429||$error->status>=500)){$this->scheduleNext($user,$resource,30);}return false;}if(!$result->observedAt||!empty($result->details['stale'])){if($deadline!==null){$this->scheduleNext($user,$resource,30);}return false;}$snapshot=$resource==='grades'?$this->grades($result):$this->attendance($result);if($snapshot===null){return false;}DB::transaction(function()use($user,$resource,$snapshot):void{if(!$this->enabled($user)){return;}$row=DB::one('SELECT observed_state FROM bars_academic_watch WHERE user_id=? AND resource=? FOR UPDATE',[$user,$resource]);if(!$row)return;$previous=$row['observed_state']===null?null:json_decode($row['observed_state'],true,32,JSON_THROW_ON_ERROR);$values=array_map(static fn(array$entry):int|float|string=>$entry['value'],$snapshot['entries']);if($previous!==null&&$previous['context']===$snapshot['context']){$this->notify($user,$resource,$previous['values'],$snapshot['entries']);}DB::run('UPDATE bars_academic_watch SET observed_state=? WHERE user_id=? AND resource=?',[json_encode(['context'=>$snapshot['context'],'values'=>$values],JSON_THROW_ON_ERROR),$user,$resource]);});return true;}private function enabled(string$user):bool{$row=DB::one("SELECT preferences->>'$.notifications.academicUpdates' AS enabled FROM user_preferences WHERE user_id=?",[$user]);return($row['enabled']??'true')==='true';}private function grades(ProviderResult$result):?array{if(empty($result->details['subjects'])){return null;}$entries=[];foreach($result->items as$item){$kind=$item['kind']??'';$mark=trim($item['display_score']??'');if(!in_array($kind,['assessment','exam','final'],true)||!preg_match('/^(?:\d+(?:[.,]\d+)?|зач[её]т|не\s*зач[её]т|зачтено|не\s+зачтено)$/uiD',$mark)){continue;}$key=hash('sha256',implode('|',[$item['subject_title'],$kind,$item['assessment_title'],$item['week']??'']));$entries[$key]=['value'=>$mark,'body'=>$item['subject_title'].' · '.$item['assessment_title'].' — '.$mark];}return['context'=>$result->details['semester']??'','entries'=>$entries];}private function attendance(ProviderResult$result):?array{$summary=$result->details['attendance']??BarsStatistics::attendance($result->details['blocks']??[]);if(!$summary['summaryAvailable']){return null;}$entries=[];foreach($summary['subjects']as$item){$entries[hash('sha256',$item['title'])]=['value'=>$item['total'],'body'=>$item['title']];}return['context'=>$summary['summaryFromTotals']?'totals':'details','entries'=>$entries];}private function notify(string$user,string$resource,array$previous,array$entries):void{$grades=$resource==='grades';foreach($entries as$key=>$entry){$old=$previous[$key]??null;if($grades?$old===$entry['value']:$entry['value']<=(int)$old){continue;}$delta=$grades?1:$entry['value']-(int)$old;$id=DB::id();$title=$grades?'Новая оценка':($delta===1?'Новый пропуск':'Новые пропуски: '.$delta);DB::run('INSERT INTO notifications(id,recipient_user_id,type,title,body,related_type,dedupe_key) VALUES(?,?,?,?,?,?,?)',[$id,$user,$grades?'bars_grade':'bars_absence',$title,mb_substr($entry['body'],0,500),$resource,'bars:'.$id]);}}}